def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_last, opp_last = history[-1]

    opp_d = 0
    for h in history:
        if h[1] == 'D':
            opp_d += 1
    opp_c = n - opp_d

    start = n - 8
    if start < 0:
        start = 0
    recent_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_d += 1

    opp_streak = 0
    for h in reversed(history):
        if h[1] == 'D':
            opp_streak += 1
        else:
            break

    my_streak = 0
    for h in reversed(history):
        if h[0] == 'D':
            my_streak += 1
        else:
            break

    myD_total = 0
    myD_to_C = 0
    myC_total = 0
    myC_to_C = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            myD_total += 1
            if history[i + 1][1] == 'C':
                myD_to_C += 1
        else:
            myC_total += 1
            if history[i + 1][1] == 'C':
                myC_to_C += 1

    punish_D = myD_total - myD_to_C

    independent = False
    if myD_total >= 4 and myC_total >= 4:
        rateD = (myD_to_C + 1.0) / (myD_total + 2.0)
        rateC = (myC_to_C + 1.0) / (myC_total + 2.0)
        diff = rateD - rateC
        if diff < 0:
            diff = -diff
        if diff <= 0.15:
            independent = True

    exploitable = False
    if opp_c * 100 >= n * 65 and myD_to_C >= 1 and punish_D == 0:
        exploitable = True

    autonomous = False
    if n >= 18:
        wlen = 12
        start = n - wlen
        first = history[start][1]
        mixed = False
        for i in range(start + 1, n):
            if history[i][1] != first:
                mixed = True
                break
        if mixed:
            for p in range(2, 7):
                if p >= wlen:
                    break
                match = 0
                total = 0
                for i in range(start, n - p):
                    total += 1
                    if history[i][1] == history[i + p][1]:
                        match += 1
                if total >= 6 and match * 100 >= total * 88:
                    copy_match = 0
                    copy_total = 0
                    s2 = start + 1
                    if s2 < 1:
                        s2 = 1
                    for i in range(s2, n):
                        copy_total += 1
                        if history[i][1] == history[i - 1][0]:
                            copy_match += 1
                    if copy_total >= 6 and copy_match * 100 < copy_total * 64:
                        autonomous = True
                        break

    if n == 99:
        return 'D'

    if n == 98:
        if independent or exploitable or autonomous:
            return 'D'
        if punish_D == 0 or recent_d >= 3 or opp_streak >= 2:
            return 'D'
        return 'C'

    if independent or exploitable or autonomous:
        return 'D'

    hostile = False
    if recent_d >= 6 or opp_streak >= 4 or (opp_d >= 4 and opp_d * 100 >= n * 45):
        hostile = True

    if hostile:
        return 'D'

    if opp_last == 'D':
        if opp_streak == 1:
            if history[-2][0] == 'D':
                return 'C'
            return 'D'

        if my_streak >= 2:
            limit = max(4, (n * 35) // 100)
            if opp_d <= limit:
                return 'C'
            if rng.random() < 0.4:
                return 'C'
            return 'D'

        if my_streak == 1:
            if opp_streak >= 4:
                return 'C'
            return 'D'

        return 'D'

    if my_last == 'D':
        return 'C'

    return 'C'
